import json

with open('json/posts.json', 'r') as f:
    data = json.load(f)

posts = data['records']

# Group by OwnerUserId and count posts + sum scores
user_stats = {}
for post in posts:
    owner_id = post.get('OwnerUserId')
    if owner_id is not None:
        score = post.get('Score', 0)
        if owner_id not in user_stats:
            user_stats[owner_id] = {'count': 0, 'total_score': 0}
        user_stats[owner_id]['count'] += 1
        user_stats[owner_id]['total_score'] += score

# Filter users with more than 10 posts and calculate average score
result = []
for user_id, stats in user_stats.items():
    if stats['count'] > 10:
        avg_score = stats['total_score'] / stats['count']
        result.append({'OwnerUserId': user_id, 'AverageScore': avg_score})

print(f"Total users with >10 posts: {len(result)}")
print("First 5 entries:")
for r in result[:5]:
    print(r)
